<?php require __DIR__.'/../includes/bootstrap.php';require_member();$pageTitle='Book catalogue';$basePath='../';$s=$pdo->prepare('SELECT id FROM members WHERE user_id=?');$s->execute([current_user()['id']]);$mid=$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$bid=(int)$_POST['book_id'];$s=$pdo->prepare('SELECT COUNT(*) FROM reservations WHERE member_id=? AND book_id=? AND status IN("pending","approved")');$s->execute([$mid,$bid]);if($s->fetchColumn())flash('error','You already have an active reservation for this book.');else{$pdo->prepare('INSERT INTO reservations(member_id,book_id) VALUES(?,?)')->execute([$mid,$bid]);flash('success','Reservation request sent. This does not issue the book.');}redirect('books.php');}$q=trim($_GET['q']??'');$like="%$q%";$s=$pdo->prepare('SELECT * FROM books WHERE title LIKE ? OR author LIKE ? OR category LIKE ? ORDER BY title');$s->execute([$like,$like,$like]);$books=$s->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><div class="panel-head"><div><h3>Available book catalogue</h3><p>You can request a reservation. An administrator must issue the book to you.</p></div></div><form class="search-row"><input name="q" value="<?=e($q)?>" placeholder="Search title, author or category"><button class="btn">Search</button></form><div class="book-grid"><?php foreach($books as $b):?><article class="book-card"><div class="book-cover">▤</div><div class="book-info"><span class="eyebrow"><?=e($b['category']?:'GENERAL')?></span><h4><?=e($b['title'])?></h4><p><?=e($b['author'])?></p><small><?=$b['available_copies']?> available · Shelf <?=e($b['shelf']?:'—')?></small><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="book_id" value="<?=$b['id']?>"><button class="btn small" <?=$b['available_copies']<1?'disabled':''?>>Request reservation</button></form></div></article><?php endforeach;?><?php if(!$books):?><p class="empty">No matching books.</p><?php endif;?></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
